INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine vernetzte Fabrik immer ohne menschlichen Eingriff arbeitet?', 2, '[{"text": "Nein", "correct": true, "because": "Menschliche Überwachung oft nötig"}, {"text": "Ja", "correct": false, "because": "Teilautomatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie ist zentral für die Vernetzung in solchen Fabriken?', 3, '[{"text": "IoT", "correct": true, "because": "Ermöglicht Gerätekommunikation"}, {"text": "Bluetooth", "correct": false, "because": "Begrenzte Reichweite"}, {"text": "NFC", "correct": false, "because": "Kurzstreckenanwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für eine solche Fabrik typisch?', 5, '[{"text": "Sensoren", "correct": true, "because": "Erfassen Daten"}, {"text": "KI-Systeme", "correct": true, "because": "Analysieren Prozesse"}, {"text": "Robotik", "correct": true, "because": "Automatisieren Aufgaben"}, {"text": "Farbcodierung", "correct": false, "because": "Kein technischer Faktor"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cyber-physische Systeme sind Kern einer intelligenten Fabrik. b) Sie erfordern immer 5G.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, andere Netze möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung einer vernetzten Produktion?', 4, '[{"text": "Datenintegration", "correct": false, "because": "Sichert Kommunikation"}, {"text": "Sicherheitskonzepte", "correct": false, "because": "Schützen Systeme"}, {"text": "Maschinenfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine solche Fabrik immer cloudbasiert ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokale Systeme möglich"}, {"text": "Ja", "correct": false, "because": "Flexibilität in Architektur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie optimiert Prozesse in Echtzeit?', 4, '[{"text": "Big Data Analytics", "correct": true, "because": "Analysiert Datenströme"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Zu langsam"}, {"text": "Statische Modelle", "correct": false, "because": "Nicht dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Fabriken immer vollautomatisiert sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Teilautomatisierung üblich"}, {"text": "Ja", "correct": false, "because": "Menschliche Eingriffe oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Industrie 4.0 dasselbe wie eine vernetzte Fabrik?', 2, '[{"text": "Nein", "correct": true, "because": "Industrie 4.0 umfasst mehr"}, {"text": "Ja", "correct": false, "because": "Breiteres Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine vernetzte Produktion?', 5, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Optimiert Prozesse"}, {"text": "Flexibilität", "correct": true, "because": "Passt sich an"}, {"text": "Schnellere Installation", "correct": false, "because": "Kein Primärziel"}, {"text": "Bunte Visuals", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einführung einer solchen Fabrik?', 4, '[{"text": "Cybersicherheit", "correct": true, "because": "Schützt vernetzte Systeme"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Ästhetisches Design", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sensoren sind essenziell für die Datenverarbeitung. b) Sie ersetzen menschliche Arbeit komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ergänzen Arbeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine vernetzte Produktion?', 3, '[{"text": "IoT-Geräte", "correct": false, "because": "Ermöglichen Vernetzung"}, {"text": "Datenanalyse", "correct": false, "because": "Optimiert Prozesse"}, {"text": "Firmenlogo", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Sicherheit in einer solchen Fabrik gewährleiste?', 4, '[{"text": "Firewalls und Verschlüsselung einsetzen", "correct": true, "because": "Schützen Netzwerk"}, {"text": "Nur Sensoren nutzen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Schutzmaßnahmen", "correct": false, "because": "Riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Fabriken nur für Großunternehmen geeignet sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch KMUs profitieren"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System hilft, Prozesse zu simulieren?', 4, '[{"text": "Digitaler Zwilling", "correct": true, "because": "Virtuelle Nachbildung"}, {"text": "Manuelle Planung", "correct": false, "because": "Zu statisch"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Fabriken immer cloudbasiert?', 2, '[{"text": "Nein", "correct": true, "because": "Lokale Systeme möglich"}, {"text": "Ja", "correct": false, "because": "Architektur variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt KI in einer vernetzten Fabrik?', 5, '[{"text": "Prozessoptimierung", "correct": true, "because": "Analysiert Daten"}, {"text": "Vorhersagewartung", "correct": true, "because": "Erkennt Ausfälle"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein KI-Ziel"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Einführung einer solchen Fabrik unwichtig?', 3, '[{"text": "Netzwerkstabilität", "correct": false, "because": "Sichert Kommunikation"}, {"text": "Skalierbarkeit", "correct": false, "because": "Ermöglicht Wachstum"}, {"text": "Verpackungsdesign", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich eine solche Fabrik plane?', 4, '[{"text": "Risiken analysieren, IoT und KI integrieren", "correct": true, "because": "Ganzheitlicher Ansatz"}, {"text": "Nur Roboter kaufen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Plan starten", "correct": false, "because": "Riskant"}]');
